function parseRelativeTime(str) {
  if (!str) return null;

  const now = new Date();
  const text = String(str).toLowerCase().trim();
  const match = text.match(/hace\s+(\d+)\s+(minuto|minutos|hora|horas|d[ií]a|d[ií]as)/i);

  if (!match) return null;

  const amount = Number(match[1]);
  const unit = match[2];

  if (unit.startsWith('minuto')) now.setMinutes(now.getMinutes() - amount);
  else if (unit.startsWith('hora')) now.setHours(now.getHours() - amount);
  else now.setDate(now.getDate() - amount);

  return now.toISOString();
}

function normalizeLink(link) {
  if (!link) return '';
  const value = String(link).trim();
  if (value.startsWith('./')) return `https://news.google.com/${value.slice(2)}`;
  if (value.startsWith('/')) return `https://news.google.com${value}`;
  return value;
}

function truncate(text, max) {
  const value = String(text || '').trim();
  return value.length > max ? `${value.slice(0, max - 1)}...` : value;
}

const source = items[0].json;
const titles = source['Article Titles'] || [];
const links = source['Article Links'] || [];
const sources = source['Article Sources'] || [];
const times = source['Publication Times'] || [];
const snippets = source['Article Snippets'] || [];

const seen = new Set();
const out = [];
const runDate = new Date().toISOString();

for (let i = 0; i < titles.length; i++) {
  const title = truncate(titles[i], 220);
  const link = normalizeLink(links[i]);
  const sourceName = truncate(sources[i], 120);
  const timeRaw = truncate(times[i], 60);
  const snippet = truncate(snippets[i], 420);

  if (!title || !link) continue;

  const dedupeKey = `${title}__${sourceName}`.toLowerCase();
  if (seen.has(dedupeKey)) continue;
  seen.add(dedupeKey);

  out.push({
    json: {
      run_date: runDate,
      title,
      source: sourceName,
      time_raw: timeRaw || null,
      time: parseRelativeTime(timeRaw),
      link,
      snippet: snippet || null
    }
  });
}

return out.slice(0, 12);

function containsAny(text, words) {
  return words.some((word) => text.includes(word));
}

const raw = String(query || '').toLowerCase();
let category = 'internacional';
let subcategory = 'mercados';
let reason = 'La noticia parece vinculada a mercados o entorno económico general.';

if (containsAny(raw, ['banco central', 'inflacion', 'inflación', 'ipc', 'imacec', 'tasa', 'tasas', 'pib'])) {
  category = 'macroeconomia';
  subcategory = 'politica_monetaria';
  reason = 'Se detectan términos asociados a macroeconomía o política monetaria.';
} else if (containsAny(raw, ['ipsa', 'bolsa', 'acciones', 'mercado', 'mercados', 'wall street', 'bonos'])) {
  category = 'mercados';
  subcategory = 'activos_financieros';
  reason = 'Se detectan términos asociados a mercados financieros o activos.';
} else if (containsAny(raw, ['cmf', 'sp', 'superintendencia', 'regulacion', 'regulación', 'ley', 'normativa'])) {
  category = 'regulacion';
  subcategory = 'normativa_financiera';
  reason = 'Se detectan términos asociados a regulación o normativa.';
} else if (containsAny(raw, ['codelco', 'sqm', 'litio', 'cobre', 'mineria', 'minería'])) {
  category = 'commodities';
  subcategory = 'mineria_y_metales';
  reason = 'Se detectan términos asociados a cobre, litio o minería.';
} else if (containsAny(raw, ['banco de chile', 'santander', 'bci', 'itau', 'itau', 'scotiabank'])) {
  category = 'banca';
  subcategory = 'banca_comercial';
  reason = 'Se detectan referencias directas al sector bancario.';
} else if (containsAny(raw, ['empresa', 'utilidad', 'utilidades', 'ingresos', 'resultados', 'firma', 'compañia', 'compania'])) {
  category = 'empresas';
  subcategory = 'resultados_corporativos';
  reason = 'Se detectan términos asociados a empresas o resultados corporativos.';
}

return JSON.stringify({
  category,
  subcategory,
  classification_reason: reason
});

function score(text) {
  let total = 20;
  const boosts = [
    { words: ['chile', 'chileno', 'chilena', 'clp', 'ipsa'], value: 20 },
    { words: ['cobre', 'litio', 'codelco', 'sqm'], value: 20 },
    { words: ['banco central', 'cmf', 'sp', 'afp', 'hacienda'], value: 20 },
    { words: ['banco de chile', 'bci', 'santander', 'itau', 'falabella', 'copec', 'enel chile'], value: 20 },
    { words: ['inflacion', 'inflación', 'tasas', 'imacec', 'normativa', 'regulacion', 'regulación'], value: 10 }
  ];

  for (const boost of boosts) {
    if (boost.words.some((word) => text.includes(word))) total += boost.value;
  }

  return Math.max(0, Math.min(total, 100));
}

const raw = String(query || '').toLowerCase();
const relevance_score = score(raw);
let relevance_reason = 'La noticia parece de interés general con baja conexión explícita a Chile.';

if (relevance_score >= 80) {
  relevance_reason = 'La noticia muestra una conexión directa con economía chilena, activos locales o instituciones del país.';
} else if (relevance_score >= 50) {
  relevance_reason = 'La noticia tiene relación moderada con Chile o con variables relevantes para un lector de negocios local.';
} else if (relevance_score >= 30) {
  relevance_reason = 'La noticia podría afectar indirectamente a Chile, pero la relación local no es central.';
}

return JSON.stringify({ relevance_score, relevance_reason });

function has(text, words) {
  return words.some((word) => text.includes(word));
}

const raw = String(query || '').toLowerCase();
let sentiment = 'neutral';
let impact_score = 25;
let impacted_assets = [];
let actionable_flag = false;
let action = 'Monitorear desarrollo y confirmar más contexto antes de actuar.';
let confidence = 65;
let notes = 'Estimación basada en reglas simples sobre título, fuente y snippet.';

if (has(raw, ['cae', 'baja', 'retrocede', 'pierde', 'riesgo', 'crisis', 'golpe', 'caída'])) {
  sentiment = 'negative';
  impact_score += 20;
}
if (has(raw, ['sube', 'alza', 'mejora', 'crece', 'avance', 'récord', 'record'])) {
  sentiment = sentiment === 'negative' ? 'mixed' : 'positive';
  impact_score += 20;
}
if (has(raw, ['ipsa', 'acciones', 'bolsa'])) impacted_assets.push('IPSA');
if (has(raw, ['clp', 'peso chileno', 'dolar', 'dólar', 'usdclp'])) impacted_assets.push('CLP');
if (has(raw, ['cobre'])) impacted_assets.push('cobre');
if (has(raw, ['litio', 'sqm'])) impacted_assets.push('litio');
if (has(raw, ['banco', 'tasas'])) impacted_assets.push('banca');
if (has(raw, ['bonos'])) impacted_assets.push('bonos');
if (has(raw, ['retail', 'falabella'])) impacted_assets.push('retail');

impacted_assets = [...new Set(impacted_assets)];
impact_score = Math.max(0, Math.min(impact_score + impacted_assets.length * 8, 100));
actionable_flag = impact_score >= 45;
if (actionable_flag) action = 'Revisar impacto potencial en apertura de mercado y activos expuestos.';
if (impacted_assets.length === 0) notes = 'No se identificaron activos claramente impactados con las reglas actuales; podría requerir análisis adicional.';

const summary = impacted_assets.length > 0
  ? `Noticia con señal ${sentiment} y posible impacto sobre ${impacted_assets.join(', ')}.`
  : `Noticia con señal ${sentiment} y efecto de mercado poco específico con la información disponible.`;

return JSON.stringify({
  sentiment,
  impact_score,
  impacted_assets,
  summary,
  actionable_flag,
  action,
  confidence,
  notes
});

function safeParse(value) {
  if (value && typeof value === 'object') return value;

  const raw = String(value || '')
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```/, '')
    .replace(/```$/, '')
    .trim();

  return JSON.parse(raw);
}

const parsed = safeParse($json.output);
parsed.impacted_assets = Array.isArray(parsed.impacted_assets) ? parsed.impacted_assets : [];
parsed.actionable_flag = parsed.actionable_flag === true || String(parsed.actionable_flag).toLowerCase() === 'true';
return { json: parsed };
